package com.bank.flink.state;

import java.math.BigDecimal;

// A transaction: which account and how much (positive credit, negative debit).
class Transaction {
    private final String accountId;
    private final BigDecimal amount;
    private final long sourcePartition;
    private final long offset;

    Transaction(String accountId, BigDecimal amount, long sourcePartition, long offset) {
        this.accountId = accountId;
        this.amount = amount;
        this.sourcePartition = sourcePartition;
        this.offset = offset;
    }

    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
    long getSourcePartition() { return sourcePartition; }
    long getOffset() { return offset; }
}
