package com.bank.flink.state;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Reproduces per-key ValueState: each account has its OWN balance slice.
// Updating one account never touches another (keyed isolation).
class KeyedBalanceState {
    private static final Logger log = Logger.getLogger(KeyedBalanceState.class.getName());

    // In real Flink this is ValueState<BigDecimal> auto-scoped to the key.
    private final Map<String, BigDecimal> balanceByKey = new HashMap<>();

    // Called within the context of the current key (accountId).
    void update(String accountId, BigDecimal delta) {
        BigDecimal current = balanceByKey.getOrDefault(accountId, BigDecimal.ZERO);
        BigDecimal updated = current.add(delta);
        balanceByKey.put(accountId, updated);
        log.info(() -> "KEYED ValueState[" + accountId + "] " + current + " -> " + updated);
    }

    BigDecimal value(String accountId) {
        return balanceByKey.getOrDefault(accountId, BigDecimal.ZERO);
    }

    // A checkpoint would snapshot this partitioned state by key group.
    Map<String, BigDecimal> snapshot() {
        return new HashMap<>(balanceByKey);
    }

    void restore(Map<String, BigDecimal> snapshot) {
        balanceByKey.clear();
        balanceByKey.putAll(snapshot);
        log.info(() -> "KEYED state restored: " + balanceByKey);
    }
}
