package com.bank.flink.state;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Reproduces operator ListState: per SUBTASK, the last read offset of each
// input partition. This is plumbing state owned by the worker, not a key.
class SourceOffsetState {
    private static final Logger log = Logger.getLogger(SourceOffsetState.class.getName());

    private final int subtaskId;
    // partition -> last committed offset
    private final Map<Long, Long> offsets = new HashMap<>();

    SourceOffsetState(int subtaskId) {
        this.subtaskId = subtaskId;
    }

    void advance(long partition, long offset) {
        offsets.put(partition, offset);
        log.fine(() -> "OPERATOR ListState subtask " + subtaskId
                + " partition " + partition + " offset -> " + offset);
    }

    // snapshotState: what a checkpoint writes for this subtask.
    Map<Long, Long> snapshot() {
        return new HashMap<>(offsets);
    }

    // initializeState: restore after a crash so we resume, not reprocess.
    void restore(Map<Long, Long> snapshot) {
        offsets.clear();
        offsets.putAll(snapshot);
        log.info(() -> "OPERATOR state restored subtask " + subtaskId + ": " + offsets);
    }

    Map<Long, Long> getOffsets() { return offsets; }
}
