package com.bank.flink.state;

import java.math.BigDecimal;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: keyed ValueState for balances + operator ListState for
// source offsets, then a crash-and-restore to show both survive.
public class StateManagementDemo {
    private static final Logger log = Logger.getLogger(StateManagementDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new StateLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        KeyedBalanceState balances = new KeyedBalanceState();
        SourceOffsetState offsets = new SourceOffsetState(0);

        Transaction[] stream = new Transaction[] {
            new Transaction("SAV2001", new BigDecimal("1000"), 0, 100),
            new Transaction("CUR3001", new BigDecimal("500"),  0, 101),
            new Transaction("SAV2001", new BigDecimal("-200"), 0, 102),
            new Transaction("CUR3001", new BigDecimal("300"),  0, 103)
        };

        for (Transaction t : stream) {
            balances.update(t.getAccountId(), t.getAmount());   // keyed state
            offsets.advance(t.getSourcePartition(), t.getOffset()); // operator state
        }

        // CHECKPOINT: snapshot both kinds of state.
        Map<String, BigDecimal> balanceSnap = balances.snapshot();
        Map<Long, Long> offsetSnap = offsets.snapshot();
        log.info(() -> "CHECKPOINT taken. balances=" + balanceSnap + " offsets=" + offsetSnap);

        // CRASH: fresh objects (state lost in memory).
        KeyedBalanceState balancesAfter = new KeyedBalanceState();
        SourceOffsetState offsetsAfter = new SourceOffsetState(0);

        // RESTORE from checkpoint.
        balancesAfter.restore(balanceSnap);
        offsetsAfter.restore(offsetSnap);

        log.info(() -> "After restore SAV2001 balance = " + balancesAfter.value("SAV2001"));
        log.info(() -> "After restore CUR3001 balance = " + balancesAfter.value("CUR3001"));
        log.info(() -> "After restore resume offset partition 0 = " + offsetsAfter.getOffsets().get(0L));
    }
}

// ─── Would be in StateLogFormatter.java in a real project ───
class StateLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
